#!/usr/bin/env node
// C2 TMAP06 failure-input matrix (browser path, production runner).
// Every variant is generated by `gen-tmap --bad` and handed to the real
// runner: it must be refused with a stable typed error, must not produce a
// ready/exportable artifact and must not leave a downloadable file.
//
//   node run_tmap_failures.js [--port 8946]
'use strict';
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const L = require('./lib.js');

const PORT = Number(L.arg('port', '8946'));
const DIR = path.join(L.GATE, 'tmap-failures');

const VARIANTS = [
  ['tiff-renamed', 'tiff'],
  ['tmap07', 'tmap07'],
  ['truncated-header', 'truncate-header'],
  ['truncated-index', 'truncate-index'],
  ['truncated-jpeg', 'truncated-jpeg'],
  ['broken-jpeg', 'broken-jpeg'],
  ['non-jpeg', 'non-jpeg'],
  ['huge-index', 'huge-index'],
  ['huge-shrink', 'huge-shrink'],
  ['huge-length', 'huge-length'],
  ['offset-overflow', 'offset-overflow'],
  ['offset-in-index', 'offset-in-index'],
  ['zero-offset', 'zero-offset'],
  ['file-id', 'file-id'],
  ['multi-focus', 'focus-multi'],
  ['multi-file', 'multi-file'],
  ['image-format', 'image-format'],
  ['non-8bit', 'non-8bit'],
  ['progressive', 'progressive'],
  ['gray', 'gray'],
  ['small-tile', 'small-tile'],
  ['no-l1', 'no-l1'],
  ['no-l2', 'no-l2'],
  ['duplicate-slot', 'duplicate-slot'],
  ['duplicate-sub', 'duplicate-sub'],
  ['negative-origin', 'negative-origin'],
  ['block-layer2', 'block-layer2'],
  ['empty-with-records', 'empty-with-records'],
  ['ratio-step', 'ratio-step'],
  ['layer-num', 'layer-num'],
  ['img-color', 'img-color'],
];

function fixture(name, bad) {
  fs.mkdirSync(DIR, { recursive: true });
  const p = path.join(DIR, `${name}.tmap`);
  if (!fs.existsSync(p)) execFileSync(L.CLI, ['gen-tmap', p, '--bad', bad], { stdio: 'inherit' });
  return p;
}

async function main() {
  fs.mkdirSync(DIR, { recursive: true });
  const server = await L.startServer(PORT);
  process.on('exit', () => { try { server.kill('SIGKILL'); } catch { /* */ } });
  const { context, page } = await L.launch({ label: 'tmap-failures' });
  const results = [];
  try {
    await L.open(page, PORT);
    for (const [name, bad] of VARIANTS) {
      const p = fixture(name, bad);
      await L.clearJobs(page);
      await page.reload({ waitUntil: 'load' });
      await L.open(page, PORT);
      const t0 = Date.now();
      // Drive the production runner through the same file input the page
      // uses (path-based Playwright input, as a real user selection).
      await L.setFile(page, p);
      const refusal = await page.evaluate(() => window.__c2.tryStart({ profileId: 'saver' }));
      let done = null;
      let code = refusal.code;
      let message = refusal.message;
      if (!refusal.refused) {
        done = await page.evaluate(() => window.__c2.awaitDone(120000)).catch((e) => ({
          ok: false, timeout: String(e && e.message || e),
        }));
        code = done && done.error ? done.error.code : (done && done.ok ? 'converted' : 'unknown');
        message = done && done.error ? done.error.message : '';
      }
      const jobs = await page.evaluate(() => window.__c2.listJobs());
      const downloadable = jobs.filter((j) => j.state === 'ready' || j.state === 'exported');
      const downloads = await page.evaluate(() => window.__downloads || []);
      const pass = !!code && code !== 'converted' && downloadable.length === 0
        && (!done || done.ok !== true) && (!downloads || downloads.length === 0);
      results.push({
        variant: name, bad, refused: refusal.refused, code, message: String(message || '').slice(0, 200),
        converted: !!(done && done.ok), jobs: jobs.length, downloadable: downloadable.length,
        downloads: downloads.length, ms: Date.now() - t0, pass,
      });
      console.log(`${pass ? 'PASS' : 'FAIL'} ${name}: code=${code}` +
        `${refusal.refused ? ' (pre-start)' : ''} jobs=${jobs.length}`);
    }
  } finally {
    await context.close().catch(() => { /* */ });
    server.kill('SIGTERM');
  }
  const failed = results.filter((r) => !r.pass);
  L.writeJson('parity-tmap/failures.json', {
    finishedAt: new Date().toISOString(), passed: results.length - failed.length,
    failed: failed.length, results,
  });
  console.log(`TMAP FAILURE MATRIX: ${results.length - failed.length}/${results.length} passed`);
  process.exitCode = failed.length ? 1 : 0;
}

main().catch((e) => { console.error(e); process.exit(1); });
